                    )}

                    {/* Other Fields (fallback) */}
                    {otherFields.length > 0 && (
                      <section className="space-y-2">
                        <h4 className="text-[10px] font-bold text-white/40 uppercase tracking-widest">{t('genData.other')}</h4>
