                          {otherFields.map(([key, value]) => {
                            const displayKey = key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())
                            const isObject = typeof value === 'object'
                            const displayValue = isObject ? JSON.stringify(value, null, 2) : String(value)

                            return (
